(function(root){'use strict';
const L=root.Lesson,B=L.B;
const asset=name=>root.LESSON_ASSETS?.[name]||name;
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function bi(v,s,inline=false){if(typeof v==='string')return e(v);return e(v.en)+(s.language!=='en'&&v[s.language]?`<span class="${inline?'inline-trans':'trans'}" lang="${s.language==='zh'?'zh-Hans':'ko'}">${inline?' / ':''}${e(v[s.language])}</span>`:'');}
function plain(v,s){return typeof v==='string'?v:v.en+(s.language!=='en'&&v[s.language]?' / '+v[s.language]:'');}
const p=(v,s,cls='')=>`<p class="${cls}">${bi(v,s)}</p>`;
const btn=(a,label,s,cls='',attrs='')=>`<button type="button" data-action="${a}" class="${cls}" ${attrs}>${bi(label,s,true)}</button>`;
const note=(v,s,kind='')=>`<div class="note ${kind}">${bi(v,s)}</div>`;
function text(s,key,label,hint='',rows=2){return `<label class="field" for="f-${key}"><span>${bi(label,s)}</span>${hint?`<span class="small" id="hint-${key}">${bi(hint,s)}</span>`:''}<textarea id="f-${key}" data-field="${key}" rows="${rows}" maxlength="${key.includes('code')?12000:3000}" ${hint?`aria-describedby="hint-${key}"`:''}>${e(s.fields[key]||'')}</textarea></label>`;}
function input(s,key,label,hint='',attrs=''){return `<label class="field" for="f-${key}"><span>${bi(label,s)}</span>${hint?`<span class="small">${bi(hint,s)}</span>`:''}<input id="f-${key}" data-field="${key}" value="${e(s.fields[key]??'')}" maxlength="100" ${attrs}></label>`;}
function select(s,key,label,opts,hint=''){return `<label class="field" for="f-${key}"><span>${bi(label,s)}</span>${hint?`<span class="small">${bi(hint,s)}</span>`:''}<select id="f-${key}" data-field="${key}"><option value="">${e(plain(L.ui.choose,s))}</option>${Object.entries(opts).map(([k,v])=>`<option value="${e(k)}" ${s.fields[key]===k?'selected':''}>${e(plain(v,s))}</option>`).join('')}</select></label>`;}
function choices(s,key,label,opts){return `<fieldset><legend>${bi(label,s)}</legend>${Object.entries(opts).map(([k,v],i)=>`<label class="choice"><input type="radio" name="${key}" data-field="${key}" value="${e(k)}" ${s.fields[key]===k?'checked':''}><span><span class="letter">${String.fromCharCode(65+i)}</span>${bi(v,s)}</span></label>`).join('')}</fieldset>`;}
function check(s,key,label){return `<label class="text-check"><input type="checkbox" data-field="${key}" ${s.fields[key]?'checked':''}><span>${bi(label,s)}</span></label>`;}
function codeBox(s,code,id='core',label=L.editors[s.student.editor]){return `<div class="codebox"><div class="codebar"><span>${e(label)}</span>${btn('copy-code',L.ui.copy,s,'small-btn',`data-code-id="${id}"`)}</div><pre id="code-${id}" tabindex="0">${e(code)}</pre></div>`;}
const patterns=['01110/10001/10011/10101/01110','00100/01100/00100/00100/01110','01110/10001/00010/00100/11111','11110/00001/01110/00001/11110','00010/00110/01010/11111/00010','11111/10000/11110/00001/11110','01110/10000/11110/10001/01110','11111/00010/00100/01000/01000','01110/10001/01110/10001/01110','01110/10001/01111/00001/01110'];
function board(value=0){return `<div class="board" aria-label="Concept model display showing ${value}"><div class="board-top"><span>micro:bit</span><span>MEMORY LAB</span></div><div class="board-main"><button type="button" class="board-button" data-action="demo" aria-label="Add one in the concept model">A</button><div class="leds" aria-hidden="true">${patterns[value%10].replaceAll('/','').split('').map(x=>`<span class="led ${x==='1'?'on':''}"></span>`).join('')}</div><button type="button" class="board-button" data-action="demo-reset" aria-label="Reset concept model">↺</button></div><div class="pins" aria-hidden="true">${'<i></i>'.repeat(5)}</div></div>`;}
function blocks(s,variant='core'){const v=e(L.varName(s)),ic=e(L.icons[s.fields.icon]||'Heart'),step=variant==='plus2'?2:1;
 return `<div class="block-guide" aria-label="Block layout guide"><div class="block-group"><div class="block-cap">on start</div><div class="block-body"><div class="block-line">set <span class="block-slot">${v} ▾</span> to <span class="block-slot">0</span></div><div class="block-line basic">show icon <span class="block-slot">${ic} ▾</span></div></div></div><div class="block-group"><div class="block-cap event">on button <span class="block-slot">A ▾</span> pressed</div><div class="block-body"><div class="block-line">change <span class="block-slot">${v} ▾</span> by <span class="block-slot">${step}</span></div><div class="block-line basic">show number <span class="block-var">${v}</span></div></div></div>${['reset','decrease'].includes(variant)?`<div class="block-group"><div class="block-cap event">on button <span class="block-slot">B ▾</span> pressed</div><div class="block-body"><div class="block-line">${variant==='reset'?'set':'change'} <span class="block-slot">${v} ▾</span> ${variant==='reset'?'to':'by'} <span class="block-slot">${variant==='reset'?0:-1}</span></div><div class="block-line basic">show number <span class="block-var">${v}</span></div></div></div>`:''}</div>${p(B('Block layout guide, not an editable workspace. Match these block names and nesting in MakeCode.','这是积木布局指南，不是可编辑的工作区。请在 MakeCode 中匹配积木名称和嵌套位置。','편집할 수 있는 작업 공간이 아니라 블록 배치 안내입니다. MakeCode에서 블록 이름과 배치를 맞추세요.'),s,'small')}`;
}
function editorLink(s){const micro=s.student.editor==='micropython';return `<a class="button primary" href="${micro?L.links.micropython:L.links.makecode}" target="_blank" rel="noopener noreferrer">${bi(micro?B('Open micro:bit Python Editor','打开 micro:bit Python 编辑器','micro:bit Python 편집기 열기'):B('Open MakeCode website','打开 MakeCode 网站','MakeCode 웹사이트 열기'),s,true)} ↗</a>`;}
function routeGuide(s){const d=s.student.device,ed=s.student.editor;let v;
 if(d==='ipad')v=B('On iPad: open the micro:bit app → Create Code → open your Week 2 project. Use Blocks, or the language menu beside JavaScript → Python. The website button below does not launch the iPad app.','iPad：打开 micro:bit 应用 → Create Code → 打开第二周项目。使用 Blocks，或通过 JavaScript 旁的语言菜单选择 Python。下面的网站按钮不会启动 iPad 应用。','iPad에서는 micro:bit 앱 → Create Code → 2주차 프로젝트를 여세요. Blocks를 사용하거나 JavaScript 옆 언어 메뉴에서 Python을 선택하세요. 아래 웹사이트 버튼은 iPad 앱을 실행하지 않습니다.');
 else if(ed==='micropython')v=B('Use the separate micro:bit Python Editor, not the Python tab in MakeCode. Open your saved Week 2 file. The program uses from microbit import * and display commands.','使用独立的 micro:bit Python 编辑器，而不是 MakeCode 的 Python 标签。打开第二周文件。该程序使用 from microbit import * 和 display 指令。','MakeCode의 Python 탭이 아닌 별도의 micro:bit Python 편집기를 쓰세요. 2주차 파일을 여세요. from microbit import *와 display 명령을 사용합니다.');
 else if(ed==='makepython')v=B('In MakeCode, open your Week 2 project. Use the language menu beside JavaScript → Python. This is MakeCode Python: basic.show_number, not display.scroll.','在 MakeCode 中打开第二周项目，通过 JavaScript 旁的语言菜单选择 Python。这是 MakeCode Python，使用 basic.show_number，不是 display.scroll。','MakeCode에서 2주차 프로젝트를 열고 JavaScript 옆 메뉴에서 Python을 선택하세요. MakeCode Python은 display.scroll이 아닌 basic.show_number를 사용합니다.');
 else v=B('Open your Week 2 MakeCode project and choose Blocks. Use the Variables, Input and Basic drawers. Keep the same project and add the new behaviour.','打开第二周的 MakeCode 项目并选择 Blocks。使用 Variables、Input 和 Basic 分类。保留同一个项目并添加新行为。','2주차 MakeCode 프로젝트를 열고 Blocks를 선택하세요. Variables, Input, Basic 메뉴를 사용해 같은 프로젝트에 새 동작을 더하세요.');
 return note(v,s)+editorLink(s);
}
function landing(s,last){return `<div class="landing-wrap"><div class="landing-top row spread"><div class="brand">TENBY <span>Digital & Creative Arts</span></div><span class="pill purple">YEAR 8 · COMPUTING</span></div><div class="landing"><section class="landing-story"><p class="eyebrow">TERM 1 · WEEK 3 · PROJECT</p><h1>Make it<br><span>remember.</span></h1>${p(B('Smart Badge · Mission 2','智能徽章 · 任务 2','스마트 배지 · 미션 2'),s,'lead')}${p(B('Last week, your badge could react. Today, give it a variable that remembers and changes.','上周，徽章能作出回应。今天，用变量让它记住并改变信息。','지난주 배지는 입력에 반응했어요. 오늘은 변수를 사용해 정보를 기억하고 바꾸게 해 보세요.'),s,'lead')}<div class="memory-demo">${board(s.demo||0)}<div class="variable-card"><span class="mini-label">VARIABLE</span><code>score</code><span class="val">${s.demo||0}</span></div></div><p class="small">${bi(B('Try A. This is a concept model, not a code runner.','试按 A。这是概念模型，不是代码运行器。','A를 눌러 보세요. 코드 실행기가 아닌 개념 모델입니다.'),s)}</p><div class="mission-line"><div class="tags"><span class="pill">60 ${bi(B('minutes','分钟','분'),s,true)}</span><span class="pill">micro:bit</span><span class="pill">${bi(B('Create · Test · Explain','制作 · 测试 · 解释','만들기 · 시험하기 · 설명하기'),s,true)}</span></div></div></section><section class="entry-card"><p class="eyebrow">YOUR LEARNING SPACE</p><h2>${bi(B('Ready to continue your badge?','准备继续制作徽章了吗？','배지를 이어서 만들 준비가 됐나요?'),s)}</h2><form id="entryForm" novalidate><div class="two-col"><label class="field" for="studentName"><span>${bi(B('Full name','姓名','이름'),s)}</span><input id="studentName" name="name" autocomplete="name" maxlength="80" value="${e(s.entry?.name||'')}" required></label><label class="field" for="studentClass"><span>${bi(B('Class','班级','반'),s)}</span><input id="studentClass" name="className" maxlength="40" placeholder="e.g. 8A" value="${e(s.entry?.className||'')}" required></label></div><label class="field" for="entryDevice"><span>${bi(B('Which device are you using?','你使用哪种设备？','어떤 기기를 사용하나요?'),s)}</span><select id="entryDevice" name="device"><option value="">${e(plain(L.ui.choose,s))}</option>${Object.entries(L.devices).map(([k,v])=>`<option value="${k}" ${s.entry?.device===k?'selected':''}>${e(v)}</option>`).join('')}</select></label><label class="field" for="entryEditor"><span>${bi(B('Choose your coding route','选择编程方式','코딩 방식을 고르세요'),s)}</span><select id="entryEditor" name="editor">${L.allowed(s.entry?.device||'ipad').map(k=>`<option value="${k}" ${s.entry?.editor===k?'selected':''}>${e(L.editors[k])}</option>`).join('')}</select><span class="small">${bi(['ipad','tablet'].includes(s.entry?.device)?B('For this lesson, tablet routes use MakeCode. MicroPython is offered on computers and supported Android setups.','本课的平板路线使用 MakeCode。电脑和受支持的 Android 配置可选择 MicroPython。','이 수업의 태블릿 경로는 MakeCode를 사용합니다. 컴퓨터와 지원되는 Android 환경에서는 MicroPython을 선택할 수 있어요.'):B('Choose the editor you used last week. MakeCode Python and MicroPython need different code.','选择上周使用的编辑器。MakeCode Python 与 MicroPython 使用不同代码。','지난주 사용한 편집기를 고르세요. MakeCode Python과 MicroPython은 서로 다른 코드가 필요해요.'),s)}</span></label><label class="field" for="entryLanguage"><span>${bi(B('Language support','语言支持','언어 지원'),s)}</span><select id="entryLanguage" name="language">${Object.entries(L.languages).map(([k,v])=>`<option value="${k}" ${s.language===k?'selected':''}>${e(v)}</option>`).join('')}</select></label><div id="teacherEntry" ${s.entry?.name?.trim().toLowerCase()==='teacher'?'':'hidden'} class="note">Teacher mode detected · Class is optional. Teacher tools use separate local storage.</div><p id="entryError" class="error" role="alert"></p><button class="primary" type="submit">${bi(B('Start my mission','开始任务','미션 시작'),s,true)} →</button></form>${p(B('English stays visible. You may think and answer in English, Mandarin, Korean, or a mixture.','英语内容始终保留。你可以用英语、中文、韩语或混合语言思考和作答。','영어는 항상 보입니다. 영어, 중국어, 한국어 또는 언어를 섞어 생각하고 답해도 됩니다.'),s,'small')}<div class="line"></div>${last?`<div class="status-card"><strong>${bi(B('Saved work found on this browser','此浏览器有已保存的记录','이 브라우저에 저장된 작업이 있어요'),s)}</strong><p class="small">${e(last.name)} · ${e(last.className||'Teacher')}</p>${btn('resume',B('Resume saved work','继续已保存的任务','저장한 작업 이어하기'),s,'small-btn')}</div>`:''}<div class="row" style="margin-top:12px">${btn('restore',L.ui.restore,s,'quiet small-btn')}</div>${p(B('Saved only in this browser on this device. No live teacher alerts or cloud submission. On a shared device, export a backup and reset your session before leaving.','仅保存在本设备的此浏览器内，不会发送实时教师提醒或自动提交到云端。共用设备时，离开前请导出备份并重置记录。','이 기기의 이 브라우저에만 저장됩니다. 실시간 교사 알림이나 클라우드 제출은 없습니다. 공용 기기에서는 나가기 전에 백업을 저장하고 기록을 초기화하세요.'),s,'footer-note')}</section></div></div>`;}
function teacher(s){if(!s.teacher)return '';return `<div class="teacher-panel"><div class="row spread"><strong>Teacher mode · Local demonstration</strong>${btn('teacher-toggle',s.teacherOpen?'Hide controls':'Show controls',s,'small-btn')}</div>${s.teacherOpen?`<p class="small">All cards are accessible. No live class dashboard; this device only. Overrides never fill in student responses.</p><div class="two-col"><label class="field"><span>Jump to any card</span><select data-teacher="jump">${L.cards.map(c=>`<option value="${c.id}" ${c.id===s.card?'selected':''}>${L.stages[c.stage].en} · ${c.title.en}</option>`).join('')}</select></label><label class="field"><span>Preview coding route</span><select data-teacher="editor">${Object.entries(L.editors).map(([k,v])=>`<option value="${k}" ${s.student.editor===k?'selected':''}>${v}</option>`).join('')}</select></label></div><div class="row">${btn('toggle-answers',s.showAnswers?'Hide answer guidance':'Show answer guidance',s,'small-btn')}${btn('override','Record teacher override',s,'small-btn')}${btn('teacher-notes','Teacher notes',s,'small-btn')}${btn('route',L.ui.route,s,'small-btn')}</div>`:''}</div>`;}
function app(s,status,percent){const c=L.cards.find(x=>x.id===s.card)||L.cards[0],siblings=L.cards.filter(x=>x.stage===c.stage);return `<header class="topbar"><div class="identity"><span class="year-mark">8</span><div><strong>${e(s.student.name)} <span class="muted">· ${e(s.student.className||'Teacher')}</span></strong><small>T1 W3 PROJECT · SMART BADGE ${s.teacher?' · TEACHER MODE':''}</small></div></div><div class="toolbar"><span id="saveIndicator" class="save-indicator">${bi(s.saveError?L.ui.notSaved:L.ui.saved,s,true)}</span><select id="language" aria-label="Language support">${Object.entries(L.languages).map(([k,v])=>`<option value="${k}" ${s.language===k?'selected':''}>${e(v)}</option>`).join('')}</select>${s.teacher?btn('teacher-toggle','Teacher tools',s,'small-btn'):''}${btn('export',L.ui.export,s,'primary small-btn')}${btn('menu',L.ui.menu,s,'small-btn')}</div></header><div class="shell"><aside class="sidebar"><div class="row spread"><span class="side-heading" style="margin:0">${bi(B('LESSON JOURNEY','学习进程','학습 여정'),s,true)}</span><strong class="small" id="percentLabel">${percent}%</strong></div><div class="progress-track" style="margin-top:10px"><div id="progressFill" class="progress-fill" style="width:${percent}%"></div></div><p class="footer-note">${bi(B('Core work recorded · not a grade','核心任务记录进度，不是成绩','핵심 작업 기록률 · 성적이 아님'),s)}</p><nav class="journey" aria-label="Lesson stages">${L.stages.map((t,i)=>{const ids=L.cards.filter(x=>x.stage===i&&!x.optional),done=ids.length&&ids.every(x=>status(x.id)==='recorded'),review=ids.some(x=>status(x.id)==='review');return `<button type="button" data-action="stage" data-stage="${i}" class="stage-button ${i===c.stage?'active':''}" ${i===c.stage?'aria-current="step"':''}><span class="stage-num">${String(i+1).padStart(2,'0')}</span><span>${bi(t,s)}</span><span class="stage-state" aria-label="${done?'Recorded':review?'Needs review':i===5?'Optional':'Not complete'}">${done?'✓':review?'!':i===5?'○':''}</span></button>`}).join('')}</nav><div class="side-wagba"><strong>WAGBA</strong>${bi(L.objectives.wagba,s)}</div><div class="objectives">${['knowledge','skills','understanding'].map((k,i)=>`<div class="objective"><strong>${['KNOWLEDGE','SKILLS','UNDERSTANDING'][i]}</strong><p>${bi(L.objectives[k],s)}</p></div>`).join('')}</div><div class="line"></div>${btn('glossary',L.ui.glossary,s,'quiet small-btn')}</aside><main id="main" class="workspace" tabindex="-1"><div class="content-wrap"><div id="storageWarning" class="note warn" ${s.saveError?'':'hidden'}>${bi(B('Autosave is unavailable. Save a JSON backup before closing this tab.','自动保存不可用，关闭此标签页前请保存 JSON 备份。','자동 저장을 사용할 수 없어요. 탭을 닫기 전에 JSON 백업을 저장하세요.'),s)} ${btn('backup',L.ui.backup,s,'small-btn')}</div>${teacher(s)}<div class="breadcrumb"><span class="stepnum">${String(c.stage+1).padStart(2,'0')} / 08</span><span>${bi(L.stages[c.stage],s,true)}</span><span>·</span><span>${siblings.indexOf(c)+1} / ${siblings.length}</span></div>${siblings.length>1?`<div class="review-nav" aria-label="Activity cards">${siblings.map((x,i)=>btn('goto',`${i+1}${x.id===s.card?' •':''}`,s,x.id===s.card?'primary':'',`data-card="${x.id}" aria-label="${e(x.title.en)}"`)).join('')}</div>`:''}<article class="activity"><div class="activity-top"><p class="eyebrow">MISSION 2 · SMART BADGE</p><span class="pill ${status(c.id)==='review'?'amber':status(c.id)==='recorded'?'green':'purple'}">${bi(c.optional?L.ui.optional:status(c.id)==='recorded'?L.ui.recorded:status(c.id)==='review'?L.ui.review:B('In progress','进行中','진행 중'),s,true)}</span></div><h2>${bi(c.title,s)}</h2>${renderCard(s,c)}${s.teacher&&s.showAnswers?answerBox(s,c):''}${s.gate?note(B('Some evidence is still missing. Add it now, or continue with this card marked for review.','仍有部分证据未填写。可以现在补充，也可以继续并将本卡标记为待检查。','아직 빠진 증거가 있어요. 지금 채우거나 확인 필요로 표시하고 계속할 수 있어요.'),s,'warn')+btn('skip',L.ui.skip,s,'small-btn'):''}<footer class="card-footer">${btn('back',B('← Back','← 返回','← 이전'),s,'quiet',c.id==='read'?'disabled':'')}<div class="row">${c.id==='review'?btn('export',L.ui.export,s,'primary'):btn('next',c.optional?B('Continue to Learning Pitstop','前往学习检查站','학습 점검으로 이동'):L.ui.next,s,'primary')}</div></footer></article>${p(B('Your code stays in the coding editor. Your thinking and evidence stay here.','代码保存在编程编辑器中，思考与证据记录在这里。','코드는 코딩 편집기에, 생각과 증거는 여기에 남기세요.'),s,'footer-note')}</div></main></div>`;}
function answerBox(s,c){let t='';if(c.id.startsWith('do')){const q=L.questions['q'+c.id.slice(-1)];t=q.feedback.en;}else if(c.id==='trace')t='1, 2, 3, 0. Initial assignment is outside the A event / outside the repeating loop. Restart runs the initial assignment again.';else if(c.id==='test')t='Core output sequence: chosen welcome icon; 1; 3; 1 (after restart and one press). Test results are student-reported, not automatically verified.';else if(c.id==='explain')t='Look for input A; an update using old value + 1; the named variable; output of its current value. Transfer question: 1 → 3 → 5.';else if(c.id==='build')t='MakeCode Python requires global for the shared counter inside the handler. MicroPython initialization must stay above while True. Do not append a second A handler / second infinite loop.';else t='Review actual evidence. Self-reports describe learning needs, not attainment. Ask each student to demonstrate one update, including students sharing a device.';return `<div class="teacher-answer"><strong>Teacher guidance</strong><br>${e(t)}</div>`;}
function renderCard(s,c){const id=c.id,v=L.varName(s);
 if(id==='read')return p(B('Last week your badge reacted to an input. This week it will keep track of a number, then use that number in its output.','上周徽章会对输入作出回应。本周它会记录一个数字，再把这个数字用于输出。','지난주 배지는 입력에 반응했어요. 이번 주에는 숫자를 기록하고 그 숫자를 출력에 사용합니다.'),s,'lead')+`<div class="flow"><div class="surface"><strong>INPUT</strong>${bi(B('Press A','按 A','A 누르기'),s)}</div><span class="arrow">→</span><div class="surface"><strong>PROCESS</strong>${bi(B('Read → add 1 → store','读取 → 加 1 → 保存','읽기 → 1 더하기 → 저장'),s)}<br><code>score</code></div><span class="arrow">→</span><div class="surface"><strong>OUTPUT</strong>${bi(B('Show the new value','显示新值','새 값 표시'),s)}</div></div><div class="two-col"><section class="surface"><p class="mini-label">ONE NAME</p><p class="equation">score = 0</p>${p(B('score is the identifier. 0 is the starting number. = assigns the value.','score 是标识符，0 是初始数字，= 用来赋值。','score는 식별자, 0은 시작 숫자, =는 값을 대입하는 기호예요.'),s)}</section><section class="surface"><p class="mini-label">CHANGING VALUE</p><p class="equation">0 → 1 → 2 → 3</p>${p(B('The name stays the same. Each update replaces its value.','名称保持不变，每次更新会替换它的值。','이름은 그대로이고 갱신할 때마다 값이 바뀌어요.'),s)}</section></div>`+note(B('This program remembers while it runs. Restarting runs the starting assignment again, so the count returns to 0. A variable is not automatically permanent storage.','这个程序在运行时记住数值。重启会再次执行初始赋值，因此计数回到 0。变量并不会自动永久保存。','이 프로그램은 실행 중에 값을 기억해요. 재시작하면 시작 값을 다시 대입해 카운트가 0이 돼요. 변수가 자동으로 영구 저장되는 것은 아니에요.'),s)+`<details><summary>${bi(B('Try the idea before you code','编程前先体验概念','코딩 전에 개념 체험하기'),s)}</summary><div class="memory-demo">${board(s.demo||0)}<div class="variable-card"><code>score</code><span class="val">${s.demo||0}</span></div></div>${p(B('This model cycles through 0–9 to demonstrate updates. It does not run or test your code. Your real badge starts with a welcome icon; A then displays the count.','此模型在 0–9 之间循环演示更新，不会运行或测试你的代码。真正的徽章先显示欢迎图标，按 A 才显示计数。','이 모델은 0–9를 반복해 갱신을 보여 줄 뿐 코드를 실행하거나 시험하지 않아요. 실제 배지는 먼저 환영 아이콘을, A를 누르면 카운트를 보여 줍니다.'),s,'small')}</details><div class="tags">${L.glossary.slice(0,7).map(x=>btn('glossary',x[0],s,'small-btn')).join('')}</div>`+check(s,'read_ready',B('I have read how this badge will use a variable.','我已阅读徽章如何使用变量。','배지가 변수를 어떻게 사용할지 읽었어요.'));
 if(id.startsWith('do')){const key='q'+id.slice(-1),q=L.questions[key],code='score = 0\nscore = score + 1\nscore = score + 1';return p(B('Think first. Choose an answer, then check it. A mistake will not lock the next activity.','先思考，选择答案后再检查。答错不会锁住下一个活动。','먼저 생각하고 답을 고른 뒤 확인하세요. 틀려도 다음 활동으로 갈 수 있어요.'),s)+ (id==='do1'?(s.student.editor==='blocks'?`<div class="block-guide"><div class="block-line">set <span class="block-slot">score ▾</span> to <span class="block-slot">0</span></div><div class="block-line">change <span class="block-slot">score ▾</span> by <span class="block-slot">1</span></div><div class="block-line">change <span class="block-slot">score ▾</span> by <span class="block-slot">1</span></div></div>${p(B('Read these instructions from top to bottom.','从上到下阅读这些指令。','위에서 아래로 읽으세요.'),s,'small')}`:codeBox(s,code,'retrieval','Python · variable trace')):id==='do3'?'<div class="codebox"><pre>score = 0</pre></div>':'')+choices(s,key,q.prompt,q.options)+btn('check-question',L.ui.check,s,'primary',`data-key="${key}"`)+feedback(s,key);}
 if(id.startsWith('before')||/^pit[012]$/.test(id))return reflections(s,id.startsWith('pit'),Number(id.slice(-1)));
 if(id==='focus'||id==='pitfocus')return reflectionFocus(s,id==='pitfocus');
 if(id==='plan')return plan(s);
 if(id==='build')return build(s);
 if(id==='trace')return trace(s);
 if(id==='test')return test(s);
 if(id==='evidence')return evidence(s);
 if(id==='extension')return extension(s);
 if(id==='explain')return p(B('Use your own badge, code and test results. Keep the Input → Process → Output explanation; describe the variable inside the process.','使用自己的徽章、代码和测试结果。按“输入 → 处理 → 输出”解释，在处理部分说明变量。','자신의 배지, 코드, 시험 결과를 사용하세요. 입력 → 처리 → 출력 순서로 설명하고 처리에서 변수를 설명하세요.'),s)+text(s,'ipo_input',B('Input — what does the person do?','输入——使用者做什么？','입력 — 사용자는 무엇을 하나요?'))+text(s,'ipo_process',B('Process — what does your program do when that happens?','处理——发生输入时，程序做什么？','처리 — 입력이 생기면 프로그램은 무엇을 하나요?'))+text(s,'ipo_variable',B('Variable — use your identifier and one actual change.','变量——用你的标识符说明一次实际变化。','변수 — 자신의 변수 이름으로 실제 변화 하나를 설명하세요.'),B('My variable ___ changed from ___ to ___ because ___.','我的变量 ___ 从 ___ 变成 ___，因为 ___。','내 변수 ___는 ___ 때문에 ___에서 ___로 바뀌었어요.'))+text(s,'ipo_output',B('Output — what appears, and where?','输出——出现什么？在哪里出现？','출력 — 무엇이 어디에 나타나나요?'))+'<div class="line"></div>'+choices(s,'exit',L.questions.exit.prompt,L.questions.exit.options)+btn('check-question',L.ui.check,s,'small-btn','data-key="exit"')+feedback(s,'exit');
 if(id==='review')return review(s);
 return '';
}
function feedback(s,key){const ck=s.checks[key];if(!ck||ck.value!==s.fields[key])return '';return note(B(ck.correct?'This matches the trace.':'Not quite yet — compare the steps.',ck.correct?'这与跟踪结果一致。':'暂时不对——比较各步骤。',ck.correct?'추적 결과와 일치해요.':'아직 맞지 않아요. 단계를 비교해 보세요.'),s,ck.correct?'good':'warn')+p(L.questions[key].feedback,s);}
function reflections(s,after,page){const opts=after?L.phases:L.before,prefix=after?'post_':'pre_';return p(after?B('Revisit the same statements. Different parts of your learning may be in different phases. These are not grades or fixed labels.','重新检查相同陈述。不同内容可以处在不同学习阶段，这不是分数或固定标签。','같은 문장을 다시 살펴보세요. 내용마다 학습 단계가 다를 수 있어요. 성적이나 고정된 분류가 아닙니다.'):B('Knowledge, skills and understanding work together. Choose what you can actually show now, not what you hope to know later.','知识、技能和理解相互配合。根据现在实际能展示的情况选择，而不是根据希望以后知道的内容。','지식, 기능, 이해는 함께 작용해요. 나중의 희망이 아니라 지금 실제로 보여 줄 수 있는 것을 고르세요.'),s)+`<details><summary>${bi(B('School learning guide','学校学习指南','학교 학습 안내'),s)}</summary><img class="picture" src="${asset('assets/'+(after?'learning-pitstop':'types-of-learning')+'.jpg')}" alt="${after?'School Learning Pitstop reflection guide':'School Types of Learning guide'}"></details>`+L.topics.slice(page*2,page*2+2).map(t=>`<section class="reflection"><p class="eyebrow">${e(t.group)} · ${L.topics.indexOf(t)+1} / 6</p><h3>${bi(t.statement,s)}</h3>${p(after?t.evidence:t.prompt,s,'small')}${after?`<div class="prior">${bi(B('Before','之前','이전'),s,true)}: ${bi(L.before[s.fields['pre_'+t.id]]||L.ui.empty,s,true)}</div>`:''}${select(s,prefix+t.id,after?B('Where am I with this now?','我现在处于什么状态？','지금 어떤 단계인가요?'):B('What is my starting point?','我的起点是什么？','나의 출발점은 무엇인가요?'),opts)}${s.fields[prefix+t.id]?note(after&&s.fields[prefix+t.id]==='drown'?B('Ask your teacher to work through one small step with you. Saving this does not send an alert — show your teacher this screen.','请老师陪你完成一个小步骤。保存不会发送提醒，请向老师展示此画面。','선생님께 작은 단계 하나를 함께 해 달라고 요청하세요. 저장해도 알림은 가지 않으니 이 화면을 보여 주세요.'):after&&s.fields[prefix+t.id]==='tread'?B('Choose an extension that asks you to justify a design or diagnose a bug.','选择需要解释设计理由或诊断错误的延伸任务。','설계 이유를 설명하거나 버그를 찾는 심화 과제를 고르세요.'):t.practice,s,after&&s.fields[prefix+t.id]==='drown'?'warn':''):''}</section>`).join('');}
function reflectionFocus(s,after){return p(after?B('Compare your starting points with your current phases. Support needs can differ between knowledge, skills and understanding.','比较起点与现在的阶段。知识、技能和理解所需的支持可以不同。','출발점과 지금 단계를 비교하세요. 지식, 기능, 이해에서 필요한 도움이 다를 수 있어요.'):B('You will use all three kinds of learning. Pick one focus to pay particular attention to during the build.','三种学习都会用到。选择制作过程中要特别注意的一个重点。','세 가지 학습을 모두 사용해요. 만들 때 특히 집중할 하나를 고르세요.'),s)+`<div class="result-list">${L.topics.map(t=>`<div class="result-row"><span>${bi(t.title,s)}</span><span>${bi(after?L.phases[s.fields['post_'+t.id]]||L.ui.empty:L.before[s.fields['pre_'+t.id]]||L.ui.empty,s)}</span></div>`).join('')}</div><div class="line"></div>`+select(s,after?'post_focus':'focus',B('Choose one focus','重点选择','집중할 한 가지'),Object.fromEntries(L.topics.map(t=>[t.id,t.title])))+(after?text(s,'post_evidence',B('What changed? What will you try next?','有什么变化？下一步尝试什么？','무엇이 달라졌고 다음에는 무엇을 하나요?'),B('Before, I ___. My trace / test showed ___. Next I will ___ and check ___. A short answer in any language is welcome.','之前我 ___。我的跟踪表／测试显示 ___。下一步我会 ___，并检查 ___。可以用任何语言简短回答。','전에는 ___. 추적 / 시험에서 ___을 확인했어요. 다음에는 ___하고 ___을 확인할 거예요. 어떤 언어로든 짧게 답해도 돼요.')):note(B('In pairs: swap driver and navigator after the first successful test. Each student keeps their own explanation and report.','两人合作：首次测试成功后交换操作员与导航员角色。每人保留自己的解释和报告。','둘이 한다면 첫 시험 성공 후 조작자와 안내자 역할을 바꾸세요. 각자 자신의 설명과 보고서를 남깁니다.'),s));}
function plan(s){return `<div class="route-ribbon"><span>${e(L.devices[s.student.device])} · <strong>${e(L.editors[s.student.editor])}</strong></span>${btn('route',L.ui.route,s,'small-btn')}</div>`+p(B('Upgrade your Week 2 badge, not a new unrelated project. Keep the welcome icon. Give Button A the new job of updating a counter.','升级第二周徽章，而不是开始一个无关项目。保留欢迎图标，让按钮 A 执行更新计数的新任务。','새로운 별개 프로젝트가 아니라 2주차 배지를 개선하세요. 환영 아이콘은 유지하고 A에 카운터를 갱신하는 새 역할을 주세요.'),s)+select(s,'project_ready',B('Where is your Week 2 project?','你的第二周项目在哪里？','2주차 프로젝트는 어디에 있나요?'),{saved:B('I can open my saved project','我能打开已保存的项目','저장한 프로젝트를 열 수 있어요'),rebuild:B('I need the small recovery model','我需要小型恢复示例','작은 복구 예시가 필요해요'),help:B('I need help finding or opening it','我需要帮助查找或打开','찾거나 여는 데 도움이 필요해요')})+select(s,'purpose',B('What will your variable remember?','变量要记住什么？','변수는 무엇을 기억하나요?'),{presses:B('Button presses / points earned','按钮次数／获得的分数','버튼을 누른 횟수 / 얻은 점수'),sessions:B('Completed focus sessions — press A once after each session','完成的专注时段——每完成一次按 A 一次','완료한 집중 학습 횟수 — 완료할 때마다 A 누르기')})+note(B('Both choices use a counter starting at 0 and increasing by 1. A focus-session counter is not an elapsed-time timer.','两个选择都是从 0 开始、每次加 1 的计数器。专注时段计数器并不是测量经过时间的计时器。','둘 다 0에서 시작해 1씩 늘어나는 카운터입니다. 집중 학습 횟수를 세는 것은 경과 시간을 재는 타이머가 아니에요.'),s)+`<div class="two-col">${input(s,'variable',B('Variable name','变量名','변수 이름'),B('Use score, or a meaningful lowercase name such as focus_sessions. No spaces.','可用 score，或 focus_sessions 等有意义的小写名称。不要空格。','score 또는 focus_sessions 같은 의미 있는 소문자 이름을 쓰세요. 공백은 쓰지 마세요.'))}${select(s,'icon',B('Keep your welcome icon','保留欢迎图标','환영 아이콘 유지하기'),Object.fromEntries(Object.entries(L.icons).map(([k,v])=>[k,B(v,{HEART:'爱心',HAPPY:'笑脸',YES:'对勾',DIAMOND:'菱形'}[k],{HEART:'하트',HAPPY:'웃는 얼굴',YES:'체크',DIAMOND:'마름모'}[k])])))}</div>${s.fields.variable&&!L.validName(s.fields.variable)?`<p class="error">${bi(B('Use a lowercase letter first, then letters, digits or underscores. Avoid Python keywords and hardware names. The model uses score until this is valid.','以小写字母开头，之后使用字母、数字或下划线。避免 Python 关键词和硬件名称。名称有效前，示例使用 score。','소문자로 시작하고 글자, 숫자, 밑줄만 쓰세요. Python 예약어와 하드웨어 이름은 피하세요. 올바른 이름을 입력하기 전까지 예시는 score를 사용합니다.'),s)}</p>`:''}<div class="surface"><span class="mini-label">STARTING VALUE</span><p class="equation" style="margin:8px 0 0">${e(L.varName(s))} = 0</p></div>`+input(s,'device_number',B('micro:bit number / partner (optional)','micro:bit 编号／同伴（选填）','micro:bit 번호 / 짝 이름 (선택)'));
}
function build(s){const tab=s.buildTab||0,v=L.varName(s),ed=s.student.editor;let body='';
 if(tab===0)body=routeGuide(s)+`<div class="steps"><div class="step">${p(B('Save a copy of your Week 2 project before changing it. Keep your chosen welcome icon.','修改前先保存第二周项目副本，保留所选欢迎图标。','수정 전에 2주차 프로젝트 사본을 저장하고 환영 아이콘을 유지하세요.'),s)}</div><div class="step">${p(B('Create the counter at startup with value 0. Do not set it to 0 inside the Button A response.','启动时创建初始值为 0 的计数器，不要在按钮 A 的回应中将它设为 0。','시작할 때 값을 0으로 정하세요. 버튼 A의 반응 안에서 0으로 정하지 마세요.'),s)}</div><div class="step">${p(B('Replace the old A message with the counter update and display. Keep only one A response. A previous message can be moved to B later.','把原来的 A 消息替换为计数更新和显示，只保留一个 A 回应。原消息以后可以移到 B。','기존 A 메시지를 카운터 갱신과 표시로 바꾸고 A 반응은 하나만 두세요. 기존 메시지는 나중에 B로 옮길 수 있어요.'),s)}</div></div>`+note(ed==='micropython'?B('Reuse the existing while True loop. Do not paste a second loop below it: the first loop would never finish. Put the initial assignment above the loop.','使用已有的 while True 循环，不要在下面再粘贴一个循环，因为第一个循环不会结束。初始赋值放在循环上方。','기존 while True 반복문을 사용하세요. 첫 반복문이 끝나지 않으므로 그 아래 두 번째 반복문을 붙이지 마세요. 시작 값 대입은 반복문 위에 둡니다.'):B('Reuse your existing on start and on button A pressed containers / handler. Do not add a second A handler that competes for the display.','使用已有的 on start 和 on button A pressed 容器／处理函数，不要再添加另一个争用显示的 A 处理函数。','기존 on start와 on button A pressed 블록 / 함수를 사용하세요. 화면 표시가 겹치지 않도록 A 반응을 두 개 만들지 마세요.'),s,'warn');
 if(tab===1)body=p(B('Here is one small working model for your selected editor. Use it to check your changes. If your old file is unavailable, rebuild this welcome-icon badge first.','这是所选编辑器的小型可运行示例，可用于核对修改。如果旧文件无法取得，先重建这个有欢迎图标的徽章。','선택한 편집기용으로 작동하는 작은 예시입니다. 수정 내용을 확인하세요. 이전 파일이 없으면 먼저 이 환영 아이콘 배지를 다시 만드세요.'),s)+(ed==='blocks'?blocks(s)+`<div class="steps"><div class="step">${p(B('Variables → Make a Variable. Use the name in your plan. Add set … to 0 inside on start.','Variables → Make a Variable，使用计划中的名称。在 on start 中加入 set … to 0。','Variables → Make a Variable에서 계획한 이름을 만드세요. on start 안에 set … to 0을 넣으세요.'),s)}</div><div class="step">${p(B('Input → on button A pressed. Inside it: Variables → change … by 1, then Basic → show number.','Input → on button A pressed，在里面依次放入 Variables → change … by 1 和 Basic → show number。','Input → on button A pressed 안에 Variables → change … by 1, 그다음 Basic → show number를 넣으세요.'),s)}</div><div class="step">${p(B('Drag the oval variable value into show number. Do not type the variable name as text or leave a fixed 0.','把椭圆形变量值拖进 show number，不要把变量名当文字输入，也不要保留固定的 0。','타원형 변수 값을 show number에 끌어 넣으세요. 이름을 글자로 쓰거나 고정된 0을 남기지 마세요.'),s)}</div></div>`:codeBox(s,L.code(s),'core'))+note(ed==='makepython'?B('The supplied handler and global line are scaffolding. global lets the handler update the shared counter. Your learning focus is the variable update, not memorising event-handler syntax.','提供的处理函数和 global 行是学习支架。global 让函数更新共享计数器。学习重点是变量更新，而不是背诵事件处理语法。','제공된 함수와 global은 학습 도움 코드입니다. global은 함수가 공유 카운터를 바꾸게 해요. 함수 문법 암기보다 변수 갱신에 집중하세요.'):ed==='micropython'?B('The supplied loop listens for A. Keep the indentation exactly as shown. Press and release slowly; wait until scrolling finishes before pressing again.','提供的循环用于监听 A。保持示例中的缩进。慢慢按下并松开，等待滚动显示完成后再按。','제공된 반복문은 A 입력을 확인해요. 들여쓰기를 그대로 유지하세요. 천천히 눌렀다 놓고 스크롤이 끝난 뒤 다시 누르세요.'):B('The number block must be below change by 1, inside the same A event. Order and nesting both matter.','show number 必须在同一个 A 事件中位于 change by 1 下方。顺序与嵌套都很重要。','같은 A 이벤트 안에서 change by 1 아래에 show number를 두세요. 순서와 배치가 모두 중요합니다.'),s);
 if(tab===2)body=`<div class="surface"><p class="mini-label">UPDATE</p><p class="equation">${ed==='blocks'?`change ${e(v)} by 1`:`${e(v)} = ${e(v)} + 1`}</p>${p(B('Read the old value → add 1 → store the new value.','读取旧值 → 加 1 → 保存新值。','이전 값 읽기 → 1 더하기 → 새 값 저장하기.'),s)}</div>`+p(B('Run the program in your editor’s simulator. At startup, expect your welcome icon. Press A once: expect 1. Press again after the display finishes: expect 2.','在编辑器模拟器运行程序。启动时显示欢迎图标，按 A 一次应显示 1，等待显示完成后再按应显示 2。','편집기 시뮬레이터에서 실행하세요. 시작하면 환영 아이콘, A를 한 번 누르면 1, 표시가 끝난 뒤 다시 누르면 2가 나와야 해요.'),s)+`<details data-hint="update"><summary>${bi(B('Help me understand the update','帮助我理解更新','갱신 이해를 도와주세요'),s)}</summary>${p(B('Imagine the current value is 4. First calculate 4 + 1. Then store 5 using the same variable name. The next press starts with 5, not 0.','假设当前值是 4，先计算 4 + 1，再用同一个变量名保存 5。下次按键会从 5 开始，不是从 0 开始。','현재 값이 4라고 생각하세요. 먼저 4 + 1을 계산한 뒤 같은 변수 이름으로 5를 저장해요. 다음 입력은 0이 아니라 5에서 시작합니다.'),s)}</details>`+select(s,'build_status',B('What did you actually manage in your coding editor?','你在编程编辑器中实际完成了什么？','편집기에서 실제로 어디까지 했나요?'),{working:B('My welcome icon and changing count both run','欢迎图标与变化的计数都能运行','환영 아이콘과 변하는 카운트가 모두 작동해요'),model:B('The supplied model runs; my adaptation needs work','示例能运行，我的改编仍需修改','예시는 작동하지만 내 수정은 더 해봐야 해요'),help:B('I attempted the build and need help','我已尝试制作，但需要帮助','만들기를 시도했고 도움이 필요해요')});
 return `<div class="route-ribbon"><span><strong>${e(L.editors[ed])}</strong> · <code>${e(v)}</code></span>${btn('route',L.ui.route,s,'small-btn')}</div><div class="tabs" aria-label="Build steps">${[B('1 · Reuse your badge','1 · 继续使用徽章','1 · 배지 이어 만들기'),B('2 · Build the model','2 · 制作示例','2 · 예시 만들기'),B('3 · Try and explain','3 · 尝试并解释','3 · 실행하고 설명하기')].map((x,i)=>btn('build-tab',x,s,tab===i?'selected':'',`data-tab="${i}"`)).join('')}</div>`+body+`<div class="row" style="margin-top:20px">${tab>0?btn('build-tab',B('← Previous build step','← 上一个制作步骤','← 이전 제작 단계'),s,'small-btn',`data-tab="${tab-1}"`):''}${tab<2?btn('build-tab',B('Next build step →','下一个制作步骤 →','다음 제작 단계 →'),s,'primary small-btn',`data-tab="${tab+1}"`):''}</div>`;
}
function trace(s){const v=L.varName(s),ck=s.checks.trace;return p(B('Trace the core model: start at 0, add 1 for each A press. Use these rules even if you later change the badge in Extension.','跟踪核心示例：从 0 开始，每按 A 一次加 1。即使以后在延伸任务中修改徽章，本表仍使用此规则。','핵심 예시를 추적하세요. 0에서 시작해 A를 누를 때마다 1을 더합니다. 나중에 심화에서 바꾸더라도 이 표는 이 규칙을 사용하세요.'),s)+`<div class="trace-wrap"><table><thead><tr><th>${bi(B('Event','事件','이벤트'),s)}</th><th>${bi(B('Value after the event','事件后的值','이벤트 후 값'),s)} <code>${e(v)}</code></th></tr></thead><tbody><tr><td>${bi(B('Program starts','程序启动','프로그램 시작'),s)}</td><td><code>0</code></td></tr>${[B('A pressed once','第一次按 A','A 한 번 누름'),B('A pressed a second time','第二次按 A','A 두 번째 누름'),B('A pressed a third time','第三次按 A','A 세 번째 누름'),B('Program restarts; A has not been pressed yet','程序重启，还没按 A','재시작 후 아직 A를 누르지 않음')].map((x,i)=>`<tr><td><label for="trace${i+1}">${bi(x,s)}</label></td><td><input id="trace${i+1}" data-field="trace${i+1}" inputmode="numeric" maxlength="10" value="${e(s.fields['trace'+(i+1)]||'')}" aria-label="${e(x.en)} value">${ck?`<span class="${String(s.fields['trace'+(i+1)]).trim()===String([1,2,3,0][i])?'mark-ok':'mark-review'}"> ${String(s.fields['trace'+(i+1)]).trim()===String([1,2,3,0][i])?'✓':'↺'}</span>`:''}</td></tr>`).join('')}</tbody></table></div>`+btn('check-trace',B('Check my trace','检查跟踪表','추적표 확인'),s,'small-btn')+(ck?note(B(ck.correct?'All four entries match the core model.':'Review marked rows. After a restart, the starting assignment runs again.',ck.correct?'四项都符合核心示例。':'检查标记的行。重启后会再次执行初始赋值。',ck.correct?'네 값 모두 핵심 예시와 일치해요.':'표시된 줄을 확인하세요. 재시작하면 시작 값을 다시 대입합니다.'),s,ck.correct?'good':'warn'):'')+`<details data-hint="trace"><summary>${bi(B('Trace help: one event at a time','跟踪提示：一次只看一个事件','추적 도움: 한 번에 한 이벤트'),s)}</summary>${p(B('Keep a finger on the current value. An A press adds 1 to it. Restart is different: it runs the instruction that sets the counter to 0.','手指指着当前值。按 A 会在其上加 1。重启不同，它会执行把计数器设为 0 的指令。','현재 값을 손으로 짚으세요. A를 누르면 1을 더해요. 재시작은 달라요. 카운터를 0으로 정하는 명령을 실행합니다.'),s)}</details>`+text(s,'tracewhy',B('Why does the counter not go back to 0 after every A press?','为什么每次按 A 后计数器不会回到 0？','왜 A를 누를 때마다 0으로 돌아가지 않나요?'),B('The starting assignment is ___. The A response only ___.','初始赋值位于 ___。A 的回应只会 ___。','시작 값을 대입하는 곳은 ___. A의 반응은 ___만 해요.'));
}
function transferGuide(s){const d=s.student.device;return `<details><summary>${bi(B('Transfer to my physical micro:bit','传输到我的实体 micro:bit','실제 micro:bit로 전송하기'),s)}</summary>`+p(d==='ipad'?B('Use the micro:bit iOS app and MakeCode. Power the board with its battery pack, enable Bluetooth, and choose Download in the app’s editor. Follow the app’s current pairing / Bluetooth prompts for each transfer. Do not look for a USB MICROBIT drive on iPad.','使用 micro:bit iOS 应用和 MakeCode。用电池盒供电、启用蓝牙，在应用编辑器选择 Download。每次传输都按应用当前的配对／蓝牙提示操作。不要在 iPad 中查找 USB MICROBIT 盘。','micro:bit iOS 앱과 MakeCode를 사용하세요. 배터리를 연결하고 Bluetooth를 켠 뒤 앱 편집기에서 Download를 고르세요. 매번 앱의 현재 연결 안내를 따르세요. iPad에서 USB MICROBIT 드라이브를 찾지 마세요.'):d==='tablet'?B('Ask your teacher to confirm the tablet’s supported transfer route. Use the editor simulator while waiting. Do not assume that a charging cable can transfer code.','请老师确认平板支持的传输方式，等待时先用编辑器模拟器。不要假设充电线可以传输代码。','선생님께 태블릿의 전송 방식을 확인하세요. 기다리는 동안 편집기 시뮬레이터를 쓰세요. 충전 케이블이 코드도 전송한다고 가정하지 마세요.'):d==='android'?B('With a compatible Android device, use Chrome or Edge and a USB data cable / adapter. Use Download in MakeCode or Send to micro:bit in the Python Editor. Ask your teacher to check device permissions. The Android app is a MakeCode alternative; do not assume it transfers MicroPython.','兼容的 Android 设备可使用 Chrome 或 Edge 加 USB 数据线／转接头。MakeCode 选择 Download，Python 编辑器选择 Send to micro:bit。请老师检查权限。Android 应用是 MakeCode 的替代方式，不要假设它可传输 MicroPython。','지원되는 Android 기기에서는 Chrome 또는 Edge와 USB 데이터 케이블 / 어댑터를 사용하세요. MakeCode는 Download, Python 편집기는 Send to micro:bit를 선택하세요. 권한은 선생님께 확인하세요. Android 앱은 MakeCode의 대안이며 MicroPython 전송을 가정하지 마세요.'):B('Connect a USB data cable. In Chrome or Edge, use Download (MakeCode) or Send to micro:bit (Python Editor), then follow the pairing prompt. With Safari / Firefox, save the .hex file and copy it to the MICROBIT drive. Wait for transfer to finish before unplugging.','连接 USB 数据线。在 Chrome 或 Edge 中选择 Download（MakeCode）或 Send to micro:bit（Python 编辑器），按提示连接。Safari／Firefox 可保存 .hex 文件并复制到 MICROBIT 盘。传输结束后才拔线。','USB 데이터 케이블을 연결하세요. Chrome 또는 Edge에서는 Download(MakeCode)나 Send to micro:bit(Python 편집기)를 누르고 연결 안내를 따르세요. Safari / Firefox에서는 .hex 파일을 저장해 MICROBIT 드라이브로 복사하세요. 전송 완료 후 분리하세요.'),s)+`<a href="${d==='ipad'||d==='android'?L.links.mobile:L.links.transfer}" target="_blank" rel="noopener noreferrer">${bi(B('Official transfer guidance','官方传输指南','공식 전송 안내'),s,true)} ↗</a></details>`;}
function test(s){return p(B('Use your real program in the coding editor first. Run these four tests in order. Predict each output before the action; record what actually happened, even when it differs.','先在编程编辑器测试自己的程序。按顺序执行四个测试，操作前先预测输出，再记录实际结果，即使它与预期不同。','먼저 편집기에서 자신의 프로그램을 사용하세요. 네 시험을 순서대로 하며 동작 전에 출력을 예측하고, 달라도 실제 결과를 적으세요.'),s)+select(s,'test_env',B('Where are these test results from?','这些测试结果来自哪里？','이 시험 결과는 어디에서 얻었나요?'),{simulator:B('My coding editor’s simulator','我的编程编辑器模拟器','내 코딩 편집기의 시뮬레이터'),physical:B('My physical micro:bit','我的实体 micro:bit','내 실제 micro:bit'),blocked:B('Not running yet — I am recording the barrier','暂时无法运行——记录障碍','아직 실행하지 못해 문제를 기록 중이에요')})+note(B('Use the core rules: start at 0, add 1. Press slowly and wait for the display. If something will not run, write “not running” rather than inventing a result.','使用核心规则：从 0 开始，每次加 1。慢慢按并等待显示。无法运行时，请写“无法运行”，不要编造结果。','핵심 규칙은 0부터 1씩 증가입니다. 천천히 누르고 표시를 기다리세요. 작동하지 않으면 결과를 만들지 말고 “실행 안 됨”이라고 적으세요.'),s)+L.testRows.map((x,i)=>`<section class="surface" style="margin-bottom:16px"><p class="eyebrow">TEST ${i+1}</p><h3>${bi(x,s)}</h3><div class="two-col">${input(s,'expect'+i,B('I expect…','我预测……','예상 결과…'))}${input(s,'actual'+i,B('I observed…','我观察到……','관찰한 결과…'))}</div></section>`).join('')+transferGuide(s)+select(s,'physical_status',B('Physical-device checkpoint','实体设备检查点','실제 기기 확인'),{worked:B('Transferred and tested on a physical micro:bit','已传输并在实体 micro:bit 测试','실제 micro:bit로 전송하고 시험했어요'),waiting:B('Simulator works; physical transfer needs help','模拟器正常，实体传输需要帮助','시뮬레이터는 작동하며 실제 전송은 도움이 필요해요'),unavailable:B('No physical micro:bit available today','今天没有实体 micro:bit','오늘 실제 micro:bit가 없어요'),notyet:B('The program is not running yet','程序暂时无法运行','프로그램이 아직 작동하지 않아요')})+text(s,'test_note',B('One fix, one successful check, or the exact barrier','一个修正、一次成功检查或具体障碍','수정 하나, 성공한 확인 하나 또는 정확한 문제'),B('I expected ___. I observed ___. I changed / checked ___ and then ___. Connection difficulties are not treated as a wrong concept.','我预测 ___，实际观察到 ___。我修改／检查了 ___，然后 ___。连接困难不等于概念错误。','___을 예상했지만 ___을 관찰했어요. ___을 바꾸거나 확인한 뒤 ___했어요. 연결 문제를 개념 오류로 보지 않습니다.'));
}
function evidence(s){return p(B('Keep one clear image of your own code or blocks. Add a device photo if possible. Avoid faces or other students’ personal details. Captions should identify what the evidence shows.','保留自己代码或积木的清晰截图，能做到的话再加设备照片。避免拍到脸部或其他学生个人信息，说明文字应指出证据展示什么。','자신의 코드나 블록을 선명하게 찍으세요. 가능하면 기기 사진도 더하세요. 얼굴이나 다른 학생 개인정보는 피하고 무엇을 보여 주는지 설명을 붙이세요.'),s)+`<div class="dropzone"><strong>${bi(B('Add screenshots / photos','添加截图／照片','스크린샷 / 사진 추가'),s)}</strong><p class="small">${bi(B('Choose an image, paste a screenshot here, or drag an image onto this box. Up to 4 images; JPEG, PNG or WebP.','选择图片、在此粘贴截图，或拖入图片。最多 4 张，支持 JPEG、PNG 或 WebP。','이미지를 고르거나 스크린샷을 붙여 넣거나 이 상자로 끌어오세요. 최대 4장, JPEG, PNG, WebP를 지원해요.'),s)}</p><input id="evidenceFile" type="file" accept="image/jpeg,image/png,image/webp" multiple aria-label="Add evidence images"><div class="row" style="justify-content:center">${btn('camera',B('Take a photo (supported devices)','拍照（支持的设备）','사진 촬영 (지원 기기)'),s,'small-btn')}</div><input id="cameraFile" type="file" accept="image/*" capture="environment" hidden></div><div class="evidence-grid">${s.images.map((im,i)=>`<section><img class="preview-image" src="${im.data}" alt="${e(im.caption||'Student code or device evidence')}"><label class="field"><span>${bi(B('Evidence caption','证据说明','증거 설명'),s)}</span><textarea data-caption="${im.id}" maxlength="1500" rows="2">${e(im.caption||'')}</textarea></label>${btn('remove-image',B('Remove image','移除图片','사진 삭제'),s,'small-btn danger',`data-image="${im.id}"`)}</section>`).join('')}</div>`+text(s,'code_evidence',B('My final code / block description (optional)','我的最终代码／积木说明（选填）','내 최종 코드 / 블록 설명 (선택)'),B('Paste your own code here as evidence, not to run it. A screenshot can show your blocks instead.','在此粘贴自己的代码作为证据，不是在此运行。积木可改用截图。','실행용이 아니라 증거로 자신의 코드를 붙여 넣으세요. 블록은 스크린샷으로 보여 줘도 됩니다.'),5)+text(s,'evidence_alt',B('No upload available? Record an honest alternative.','无法上传？记录真实的替代证据。','올릴 수 없나요? 실제 대체 증거를 적으세요.'),B('Describe what you showed your teacher, or where your paper/code evidence is kept. An upload problem does not block your lesson.','说明向老师展示了什么，或纸本／代码证据放在哪里。上传问题不会阻止继续学习。','선생님께 보여 준 내용이나 종이 / 코드 증거의 위치를 적으세요. 업로드 문제로 수업이 막히지 않습니다.'))+'<div class="line"></div>'+p(B('Annotate the variable in your own work. Use exact code or block names.','注释自己作品中的变量，使用准确的代码或积木名称。','자신의 작업에 있는 변수에 설명을 붙이세요. 정확한 코드나 블록 이름을 쓰세요.'),s)+`<div class="two-col">${input(s,'annotation_name',B('My variable name','我的变量名','내 변수 이름'))}${input(s,'annotation_initial',B('Its starting value','它的初始值','시작 값'))}</div>`+text(s,'annotation_update',B('The instruction that changes its value','改变它的值的指令','값을 바꾸는 명령'))+text(s,'annotation_trigger',B('What makes that instruction run?','什么会触发这条指令？','무엇이 이 명령을 실행시키나요?'));
}
function extension(s){const choice=s.extensionTab||'choose';let html=p(B('Optional: use spare practical time. Your core progress does not depend on these challenges. Complete one, choose another, or continue to the Learning Pitstop.','可选：利用实践环节的剩余时间完成。核心进度不依赖延伸挑战。完成一个后可再选，也可直接前往学习检查站。','실습 시간이 남을 때 하는 선택 과제입니다. 핵심 진행률에 영향을 주지 않아요. 하나를 끝내고 더 하거나 학습 점검으로 가세요.'),s)+`<div class="tabs">${[['choose',B('Choose a challenge','选择挑战','도전 선택')],['small',B('1 · Improve','1 · 改进','1 · 개선')],['debug',B('2 · Diagnose','2 · 诊断','2 · 진단')],['two',B('3 · Two variables','3 · 两个变量','3 · 변수 두 개')]].map(([k,v])=>btn('extension-tab',v,s,k===choice?'selected':'',`data-tab="${k}"`)).join('')}</div>`;
 if(choice==='choose')return html+`<div class="stack">${[['small',B('Improve one input','改进一个输入','입력 하나 개선하기'),B('Count in twos, decrease with B, or reset with B. Explain and test the change.','每次加 2、用 B 减少，或用 B 重置。解释并测试修改。','2씩 세기, B로 줄이기, B로 초기화 중 하나를 선택하고 수정 내용을 설명하고 시험하세요.')],['debug',B('Rescue a badge that forgets','修复会忘记的徽章','계속 잊는 배지 고치기'),B('Find the reset-in-the-wrong-place bug. Optional Python stretch: investigate a string / number mismatch.','找出初始值设置位置错误的 bug。可选 Python 挑战：检查字符串与数字不匹配。','초기화 위치가 잘못된 버그를 찾으세요. 추가 Python 도전으로 문자열 / 숫자 불일치를 살펴보세요.')],['two',B('Use two variables for a reason','有理由地使用两个变量','이유 있게 변수 두 개 사용하기'),B('Give each variable a separate purpose, trace both, and justify why one is not enough.','为每个变量设不同用途，跟踪两者，并解释为什么一个不够。','변수마다 목적을 정해 둘 다 추적하고 하나로 충분하지 않은 이유를 설명하세요.')]].map(([k,t,d])=>`<section class="surface"><h3>${bi(t,s)}</h3>${p(d,s)}${btn('extension-tab',B('Try this challenge →','尝试此挑战 →','이 도전 시작 →'),s,'small-btn',`data-tab="${k}"`)}</section>`).join('')}</div>`;
 if(choice==='small'){const variant=s.fields.ext_small_choice||'plus2';return html+select(s,'ext_small_choice',B('Choose one change','选择一项修改','한 가지 수정 선택'),{plus2:B('A adds 2 instead of 1','A 每次加 2，而不是 1','A를 누르면 1 대신 2 더하기'),decrease:B('B decreases the value by 1','B 将值减 1','B로 값 1 줄이기'),reset:B('B resets the value to 0','B 将值重置为 0','B로 값을 0으로 초기화하기')})+note(B('Choose only one job for B. If B already shows a message, replace that handler or discuss another input with your teacher. Complete the core tests before testing these new rules.','只为 B 选择一个任务。如果 B 已显示消息，请替换其处理函数，或与老师讨论其他输入。先完成核心测试，再测试新规则。','B에 한 가지 역할만 주세요. B가 이미 메시지를 표시한다면 그 반응을 바꾸거나 다른 입력을 선생님과 정하세요. 핵심 시험을 끝낸 뒤 새 규칙을 시험하세요.'),s)+(s.student.editor==='blocks'?blocks(s,variant):codeBox(s,L.code(s,variant),'extension-small'))+text(s,'ext_small_explain',B('What changed, and how did you test it?','改了什么？如何测试？','무엇을 바꾸고 어떻게 시험했나요?'),B('From value ___, my input ___ should give ___. I observed ___.','从值 ___ 开始，输入 ___ 后应得到 ___。我观察到 ___。','값 ___에서 입력 ___를 주면 ___가 되어야 해요. 실제로 ___을 관찰했어요.'))+btn('save-extension',B('Record this challenge','记录此挑战','도전 기록하기'),s,'small-btn');}
 if(choice==='debug'){const v=L.varName(s);const bug=s.student.editor==='blocks'?`<div class="block-guide"><div class="block-group"><div class="block-cap event">on button <span class="block-slot">A ▾</span> pressed</div><div class="block-body"><div class="block-line">set <span class="block-slot">${e(v)} ▾</span> to <span class="block-slot">0</span></div><div class="block-line">change <span class="block-slot">${e(v)} ▾</span> by <span class="block-slot">1</span></div><div class="block-line basic">show number <span class="block-var">${e(v)}</span></div></div></div></div>`:s.student.editor==='micropython'?codeBox(s,`from microbit import *\n\nwhile True:\n    if button_a.was_pressed():\n        ${v} = 0\n        ${v} = ${v} + 1\n        display.scroll(${v})\n    sleep(20)`,'bug','Incorrect example · do not copy into your final program'):codeBox(s,`${v} = 0\n\ndef on_button_pressed_a():\n    global ${v}\n    ${v} = 0\n    ${v} = ${v} + 1\n    basic.show_number(${v})\n\ninput.on_button_pressed(Button.A, on_button_pressed_a)`,'bug','Incorrect example · do not copy into your final program');return html+p(B('This incorrect program always shows 1 when A is pressed. Diagnose it before revealing the hint.','这个错误程序每次按 A 都显示 1。先诊断，再查看提示。','이 잘못된 프로그램은 A를 누를 때마다 1만 보여 줘요. 힌트를 보기 전에 원인을 찾으세요.'),s)+bug+choices(s,'ext_debug_cause',B('Why does it forget the previous count?','为什么会忘记之前的计数？','왜 이전 카운트를 잊나요?'),{reset:B('It sets the counter to 0 inside every A response','每次 A 回应内部都把计数器设为 0','A 반응마다 안에서 카운터를 0으로 정해요'),display:B('Displaying a value always deletes it','显示值总会删除它','값을 표시하면 항상 삭제돼요'),button:B('Button A cannot work with variables','按钮 A 无法与变量配合','A 버튼은 변수를 사용할 수 없어요')})+text(s,'ext_debug_fix',B('Which instruction would you move or remove, and where?','你会移动或删除哪条指令？移到哪里？','어떤 명령을 옮기거나 지우고 어디에 둘 건가요?'))+text(s,'ext_debug_explain',B('Trace the repaired program through two presses. Explain the difference.','跟踪修复后的程序按两次的结果，并解释差别。','고친 프로그램에서 두 번 누른 값을 추적하고 차이를 설명하세요.'))+`<details data-hint="extension-reset"><summary>${bi(B('Reveal a debugging hint','显示调试提示','디버깅 힌트 보기'),s)}</summary>${p(B('The starting value belongs at startup, not inside the repeating A response. After the repair, the first two presses should show 1, then 2.','初始值应在启动时设置，不在重复的 A 回应中设置。修复后前两次应显示 1、2。','시작 값은 반복되는 A 반응 안이 아니라 시작 시 정해야 해요. 고치면 처음 두 번에 1, 2가 나와야 합니다.'),s)}</details><details data-hint="extension-types"><summary>${bi(B('Python stretch: number or text?','Python 挑战：数字还是文字？','Python 추가 도전: 숫자와 글자'),s)}</summary><div class="codebox"><pre>score = "0"\nscore = score + 1</pre></div>${p(B('"0" is text, while 1 is a number. In MicroPython, adding them raises a TypeError. Use 0 without quotation marks for a numeric counter, whichever editor you use.','"0" 是文字，而 1 是数字。在 MicroPython 中将两者相加会产生 TypeError。无论使用哪种编辑器，数字计数器都应使用不带引号的 0。','"0"은 글자이고 1은 숫자예요. MicroPython에서 둘을 더하면 TypeError가 발생해요. 어떤 편집기를 사용하든 숫자 카운터에는 따옴표 없는 0을 사용하세요.'),s)}</details>`+btn('save-extension',B('Record this challenge','记录此挑战','도전 기록하기'),s,'small-btn');}
 return html+p(B('A second variable must do something useful. For example, keep the count in score and the amount added in step. Then the update uses both: score = score + step.','第二个变量必须有实际用途。例如用 score 保存计数，用 step 保存每次增加的量。更新时使用两者：score = score + step。','두 번째 변수에는 실제 쓸모가 있어야 해요. 예를 들어 score는 카운트, step은 증가량을 저장하면 score = score + step으로 둘 다 사용합니다.'),s)+input(s,'ext_two_name',B('Second variable name','第二个变量名','두 번째 변수 이름'))+text(s,'ext_two_purpose',B('What will it store, and what is its starting value?','它存储什么？初始值是什么？','무엇을 저장하고 시작 값은 무엇인가요?'))+text(s,'ext_two_code',B('Show how both variables are used in your code or blocks','展示代码或积木如何使用两个变量','코드나 블록에서 두 변수를 어떻게 쓰는지 보여 주세요'),'',4)+text(s,'ext_two_trace',B('Trace both values through startup and two A presses','跟踪启动和两次按 A 后两个变量的值','시작과 A 두 번 입력에서 두 값을 추적하세요'),B('Start: score ___, step ___. A once: ___. A twice: ___.','开始：score ___，step ___。按 A 一次：___。按两次：___。','시작: score ___, step ___. A 한 번: ___. A 두 번: ___.'))+text(s,'ext_two_explain',B('Why are two variables useful here?','这里为什么需要两个变量？','여기서 두 변수가 왜 유용한가요?'),B('Explain the distinct job of each one. An unused extra variable is not an improvement.','解释两者不同的任务。添加一个未使用的变量不算改进。','각각의 다른 역할을 설명하세요. 사용하지 않는 변수 추가는 개선이 아닙니다.'))+btn('save-extension',B('Record this challenge','记录此挑战','도전 기록하기'),s,'small-btn');
}
function review(s){return p(B('Your PDF includes the trace, test records, annotations, images, reflections and recorded attempts. Unfinished work stays visible as unfinished. Exporting does not submit it to your teacher.','PDF 包含跟踪表、测试记录、注释、图片、反思和已记录的尝试。未完成内容会明确标示。导出不会自动提交给老师。','PDF에는 추적표, 시험 기록, 설명, 사진, 성찰, 시도 기록이 포함됩니다. 미완료는 그대로 표시돼요. 내보내기만으로 선생님께 제출되지는 않습니다.'),s)+`<div class="surface"><div class="row spread"><div><p class="mini-label">LEARNING REPORT</p><h3>${e(s.student.name)} · ${e(s.student.className||'Teacher')}</h3><p class="small">${e(L.devices[s.student.device])} · ${e(L.editors[s.student.editor])}</p></div>${btn('report',L.ui.report,s,'primary')}</div></div>`+check(s,'review_checked',B('I have checked my name, class, evidence and unfinished sections in the report.','我已检查报告中的姓名、班级、证据和未完成部分。','보고서의 이름, 반, 증거, 미완료 부분을 확인했어요.'))+`<div class="row">${btn('export',L.ui.export,s,'primary')}${btn('backup',L.ui.backup,s)}${btn('print',B('Print / Save as PDF','打印／另存为 PDF','인쇄 / PDF로 저장'),s)}</div>`+note(B('Save your PDF, then upload it to the Week 3 Project assignment your teacher identifies in Teams. Check the upload and complete the Teams submission yourself. Keep the JSON backup to resume on another device.','保存 PDF 后，上传到老师指定的 Teams 第三周项目作业。检查上传并自行完成 Teams 提交。保留 JSON 备份，以便在其他设备继续。','PDF를 저장하고 선생님이 지정한 Teams 3주차 프로젝트 과제에 올리세요. 업로드를 확인하고 Teams 제출까지 직접 완료하세요. 다른 기기에서 이어 하려면 JSON 백업을 보관하세요.'),s)+`<div class="steps"><div class="step">${p(B('Save your code in the coding editor too. This app cannot retrieve it automatically.','也在编程编辑器保存代码。本应用无法自动取得你的代码。','코딩 편집기에서도 코드를 저장하세요. 이 앱은 코드를 자동으로 가져올 수 없어요.'),s)}</div><div class="step">${p(B('Wait for transfer to finish. Unplug gently and return your numbered micro:bit, cable and battery pack.','等待传输完成后轻轻拔线，归还有编号的 micro:bit、线缆和电池盒。','전송이 끝나면 조심히 분리하고 번호가 있는 micro:bit, 케이블, 배터리를 반납하세요.'),s)}</div><div class="step">${p(B('On a shared device, make sure your backup is saved before resetting this lesson.','共用设备时，重置本课之前确认备份已保存。','공용 기기에서는 수업 기록을 초기화하기 전에 백업이 저장됐는지 확인하세요.'),s)}</div></div>`;}
function modal(title,body,s){return `<div class="row spread" style="margin-bottom:18px"><h3 style="margin:0">${bi(title,s)}</h3>${btn('close',L.ui.close,s,'small-btn')}</div>${body}`;}
function glossary(s){return modal(L.ui.glossary,L.glossary.map(([word,def,term])=>`<section class="reflection"><h3><code>${e(word)}</code>${s.language==='en'?'':` <span class="inline-trans">${e(term[s.language])}</span>`}</h3>${p(def,s)}</section>`).join(''),s);}
function routeForm(s){return modal(L.ui.route,`<form id="routeForm"><label class="field"><span>${bi(B('Device','设备','기기'),s)}</span><select name="device" id="routeDevice">${Object.entries(L.devices).map(([k,v])=>`<option value="${k}" ${s.student.device===k?'selected':''}>${e(v)}</option>`).join('')}</select></label><label class="field"><span>${bi(B('Coding editor','编程编辑器','코딩 편집기'),s)}</span><select name="editor" id="routeEditor">${L.allowed(s.student.device).map(k=>`<option value="${k}" ${s.student.editor===k?'selected':''}>${e(L.editors[k])}</option>`).join('')}</select></label>${note(B('Changing route keeps your answers and images, but marks practical evidence for review. Existing code in the external editor is not converted or moved. Record any new testing after you switch.','更换路线会保留答案与图片，但把实践证据标记为待检查。外部编辑器里的代码不会自动转换或移动。切换后请记录新的测试。','경로를 바꿔도 답과 사진은 남지만 실습 증거는 확인 필요로 표시됩니다. 외부 편집기 코드는 변환되거나 이동하지 않아요. 전환 후 새 시험 결과를 기록하세요.'),s,'warn')}<button class="primary" type="submit">${bi(B('Apply route','应用新路线','경로 적용'),s,true)}</button></form>`,s);}
function teacherNotes(s){return modal('Teacher notes',`<p><strong>Outcome:</strong> students add a numeric variable to the Week 2 badge, trace it, test it and explain its update. Keep initialization out of the Button A response.</p><p><strong>60-minute guide:</strong> Read now 3; Do now 4; Types of learning 5; Main task 1 16; Main task 2 18; Learning Pitstop 4; Plenary including export 10. Extension uses spare practical time, not extra time.</p><p><strong>Device routing:</strong> iPad and unknown tablets use MakeCode in this introductory lesson. Computers offer all three routes; Android MicroPython needs a supported cable/browser setup. The iPad policy is a teaching simplification, not a claim that every advanced MicroPython/iPad workflow is impossible. Official pages differ on newer iPad MicroPython support; test your managed devices before changing this policy.</p><p><strong>Before teaching:</strong> test Bluetooth/app permissions, USB data cables, board numbers and PDF download on school devices. Host over HTTPS for tablets. Simulator-only records are valid contingency evidence, not proof of physical transfer.</p><p><strong>Assessment:</strong> question/trace checks are automatic, while photographs, code, explanations, physical tests and K/S/U self-reports require teacher review. Each partner explains one update independently. An idle board / unavailable cable is not a conceptual failure.</p><p><strong>Prior learning:</strong> preserve the welcome icon and reuse the existing event handler/loop. The core counter is not an actual focus timer. A variable is runtime state, not automatic permanent storage. MakeCode’s numeric type is not a separate integer declaration.</p><p><strong>Storage:</strong> no backend, analytics or live teacher dashboard. Typing teacher is a convenience switch, not secure authentication. Teacher work is isolated from student profiles. JSON/PDF files contain student data; share through school-approved channels.</p><p><strong>Language:</strong> English with Simplified Chinese or Korean underneath. Code keywords remain in English. Have a bilingual colleague review terminology for your cohort.</p><p>Sources and deployment details are included in README.md and SOURCES.md.</p>`,s);}
root.Views={e,bi,plain,p,btn,note,text,input,select,choices,check,codeBox,board,blocks,landing,app,modal,glossary,routeForm,teacherNotes};
})(window);
